INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '4a3ca054-c932-5bc6-a1de-a64e5dad743a', '8ef27091-7ad2-5d13-a4ab-6aeb006374e8',
  'Tìm độ phức tạp của giải thuật sau

```python
def count_occurrences(a, x, lo, hi):
    if lo > hi: return 0
    mid = (lo + hi) / 2
    if a[mid] < x: return count_occurrences(a, x, mid + 1, hi)
    if a[mid] > x: return count_occurrences(a, x, lo, mid - 1)
    return 1 + count_occurrences(a, x, lo, mid - 1) + count_occurrences(a, x, mid + 1, hi)

count_occurrences(a, x, 0, len(a) - 1)
#với n=len(a)
```

Lựa chọn:
- a. O(logn)
- b. O(1)
- c. O(n)
- d. O(n^2)', 37
);

