INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'e59c7af6-ead8-576f-b822-391c8f414f00', '8ef27091-7ad2-5d13-a4ab-6aeb006374e8',
  'Cho hàm

```cpp
void fun(Queue *Q)
{
    Stack S; // Say it creates an empty stack S
    // Run while Q is not empty
    while (!isEmpty(Q))
    {
        // deQueue an item from Q and push the dequeued item to S
        push(&S, deQueue(Q));
    }

    // Run while Stack S is not empty
    while (!isEmpty(&S))
    {
        // Pop an item from S and enqueue the popped item to Q
        enqueue(Q, pop(&S));
    }
} 
```

Hàm trên thực hiện chức năng gì đối với Q?

Lựa chọn:
- Chuyển phần tử cuối và đưa lên đầu Q
- Loại bỏ các phần tử của Q
- Xóa bỏ phần tử cuối của Q
- Đảo ngược Q', 44
);

