INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '7733037d-93ed-5ed7-93a9-20df0a59bb66', '8ef27091-7ad2-5d13-a4ab-6aeb006374e8',
  'Sau khi thực hiện hàm `fun()` trên danh sách `2 -> 4 -> 6 -> 8 -> 10 -> 12`, kết quả xuất ra màn hình là:

```cpp
void fun(struct node* start)
{
    if(start == NULL)
        return;
    printf("%d ", start->data);

    if(start->next != NULL )
        fun(start->next->next);
    printf("%d ", start->data);
}
```

Lựa chọn:
- 1 3 5 5 3
- 2 6 10 10 6 2
- 2 6 10 6 2
- 2 4 6 8 10 10 8 6 4 2', 59
);

